from flask import Flask, Blueprint, jsonify

# Create a Blueprint for users routes
users_bp = Blueprint('users', __name__)

@users_bp.route('/')
def list_users():
    return jsonify([
        {'id': 1, 'name': 'Alice'},
        {'id': 2, 'name': 'Bob'}
    ])

@users_bp.route('/<int:user_id>')
def get_user(user_id):
    return jsonify({'id': user_id, 'name': f'User {user_id}'})

@users_bp.route('/', methods=['POST'])
def create_user():
    return jsonify({'id': 3, 'name': 'Charlie'}), 201

@users_bp.route('/<int:user_id>', methods=['PUT'])
def update_user(user_id):
    return jsonify({'id': user_id, 'name': f'Updated User {user_id}'})

@users_bp.route('/<int:user_id>', methods=['DELETE'])
def delete_user(user_id):
    return '', 204

# Create and configure the main Flask application
app = Flask(__name__)

# Register the users Blueprint with URL prefix
app.register_blueprint(users_bp, url_prefix='/users')

@app.route('/')
def home():
    return jsonify({'message': 'Welcome to Flask App', 'endpoints': ['/users', '/users/<id>']})

if __name__ == '__main__':
    app.run(debug=True, port=5000)

